using System; using System.Collections.Generic; using UnityEngine; using UnityEditor; using UnityEngine.Rendering;
namespace SoldierKit {
public class SoldierBuilder:EditorWindow {
 int resolution=1024; int sides=32; string folder; Transform root; Dictionary<string,Transform> bones=new(); List<HumanBone> human=new(); Material cloth,armor,black,skin,metal; 
 [MenuItem("Tools/AYUTTHAYA/Build Soldier")] static void Open()=>GetWindow<SoldierBuilder>("Soldier Builder");
 void OnGUI(){EditorGUILayout.HelpBox("Creates a stylized procedural humanoid prefab. No scene changes.",MessageType.Info);resolution=EditorGUILayout.IntPopup("Texture",resolution,new[]{"512","1024","2048"},new[]{512,1024,2048}); sides=EditorGUILayout.IntSlider("Geometry sides",sides,12,64);if(GUILayout.Button("Generate Soldier Prefab"))Build();}
 Transform Bone(string n,string parent,Vector3 pos,string humanName=null){var t=new GameObject(n).transform;t.SetParent(parent==null?root:bones[parent],false);t.localPosition=pos;bones[n]=t;if(humanName!=null)human.Add(new HumanBone{boneName=n,humanName=humanName,limit=new HumanLimit{useDefaultValues=true}});return t;}
 void Build(){folder="Assets/SoldierKit/Generated_"+DateTime.Now.ToString("yyyyMMdd_HHmmss_fff");AssetDatabase.CreateFolder("Assets/SoldierKit",System.IO.Path.GetFileName(folder));root=new GameObject("ProceduralSoldier").transform;bones.Clear();human.Clear();try{
 cloth=Mat("Camouflage",new Color(.30f,.34f,.20f),true,.15f);armor=Mat("Armor",new Color(.25f,.27f,.16f),false,.2f);black=Mat("Rubber",new Color(.10f,.11f,.10f),false,.24f);skin=Mat("Skin",new Color(.61f,.43f,.32f),false,.22f);metal=Mat("Metal",new Color(.19f,.20f,.18f),false,.48f);
 Bone("Hips",null,new Vector3(0,.91f,0),"Hips");Bone("Spine","Hips",new Vector3(0,.16f,0),"Spine");Bone("Chest","Spine",new Vector3(0,.19f,0),"Chest");Bone("Neck","Chest",new Vector3(0,.21f,0),"Neck");Bone("Head","Neck",new Vector3(0,.12f,0),"Head");
 Shape("Pelvis","Hips",Vector3.zero,new Vector3(.19f,.16f,.12f),cloth);Shape("Torso","Spine",new Vector3(0,.10f,0),new Vector3(.23f,.28f,.135f),cloth);Shape("Vest","Chest",new Vector3(0,-.08f,.035f),new Vector3(.235f,.22f,.15f),armor);Shape("Backpack","Chest",new Vector3(0,-.05f,-.18f),new Vector3(.19f,.23f,.10f),armor);Shape("HeadMesh","Head",new Vector3(0,.055f,0),new Vector3(.10f,.135f,.105f),skin);Shape("Helmet","Head",new Vector3(0,.115f,-.012f),new Vector3(.135f,.105f,.135f),cloth);Shape("Mask","Head",new Vector3(0,.015f,.055f),new Vector3(.10f,.075f,.065f),armor);
 for(int i=0;i<3;i++)Box("Pouch"+i,"Chest",new Vector3((i-1)*.115f,-.10f,.19f),new Vector3(.105f,.19f,.08f),armor);
 foreach(var side in new[]{"Left","Right"}){float s=side=="Left"?1:-1; Bone(side+"Shoulder","Chest",new Vector3(s*.15f,.12f,0),side+"Shoulder");Bone(side+"UpperArm",side+"Shoulder",new Vector3(s*.095f,0,0),side+"UpperArm");Bone(side+"LowerArm",side+"UpperArm",new Vector3(s*.29f,0,0),side+"LowerArm");Bone(side+"Hand",side+"LowerArm",new Vector3(s*.26f,0,0),side+"Hand");
 Shape(side+"Sleeve",side+"UpperArm",new Vector3(s*.135f,0,0),new Vector3(.18f,.079f,.083f),cloth);Shape(side+"Forearm",side+"LowerArm",new Vector3(s*.12f,0,0),new Vector3(.15f,.063f,.067f),cloth);Shape(side+"Glove",side+"Hand",new Vector3(s*.065f,0,0),new Vector3(.085f,.042f,.056f),black);
 Bone(side+"UpperLeg","Hips",new Vector3(s*.095f,-.03f,0),side+"UpperLeg");Bone(side+"LowerLeg",side+"UpperLeg",new Vector3(0,-.41f,0),side+"LowerLeg");Bone(side+"Foot",side+"LowerLeg",new Vector3(0,-.39f,0),side+"Foot");Bone(side+"Toes",side+"Foot",new Vector3(0,-.035f,.13f),side+"Toes");Shape(side+"Thigh",side+"UpperLeg",new Vector3(0,-.19f,0),new Vector3(.108f,.25f,.11f),cloth);Shape(side+"Calf",side+"LowerLeg",new Vector3(0,-.18f,0),new Vector3(.083f,.23f,.084f),cloth);Shape(side+"KneePad",side+"LowerLeg",new Vector3(0,-.025f,.079f),new Vector3(.073f,.09f,.037f),armor);Shape(side+"Boot",side+"Foot",new Vector3(0,-.025f,.065f),new Vector3(.077f,.095f,.16f),black);}
 // Build avatar from the actual hierarchy.
 var sk=new List<SkeletonBone>();foreach(var t in root.GetComponentsInChildren<Transform>()){if(t!=root&&!bones.ContainsValue(t))continue;sk.Add(new SkeletonBone{name=t.name,position=t.localPosition,rotation=t.localRotation,scale=t.localScale});}var desc=new HumanDescription{human=human.ToArray(),skeleton=sk.ToArray(),upperArmTwist=.5f,lowerArmTwist=.5f,upperLegTwist=.5f,lowerLegTwist=.5f,armStretch=.05f,legStretch=.05f,feetSpacing=0,hasTranslationDoF=false};var avatar=AvatarBuilder.BuildHumanAvatar(root.gameObject,desc);avatar.name="SoldierAvatar";AssetDatabase.CreateAsset(avatar,folder+"/Avatar.asset");var animator=root.gameObject.AddComponent<Animator>();animator.avatar=avatar;animator.applyRootMotion=false;
 var gun=new GameObject("GameRifleProp").transform;gun.SetParent(bones["RightHand"],false);gun.localPosition=new Vector3(-.05f,-.06f,.10f);gun.localRotation=Quaternion.identity;Prop(gun,"Body",new Vector3(0,0,.13f),new Vector3(.07f,.12f,.39f),metal);Prop(gun,"Stock",new Vector3(0,0,-.14f),new Vector3(.06f,.11f,.20f),black);Prop(gun,"Front",new Vector3(0,.015f,.38f),new Vector3(.045f,.045f,.22f),metal);Prop(gun,"Magazine",new Vector3(0,-.12f,.12f),new Vector3(.06f,.17f,.085f),armor);var muzzle=new GameObject("Muzzle").transform;muzzle.SetParent(gun,false);muzzle.localPosition=new Vector3(0,.015f,.50f);var fx=muzzle.gameObject.AddComponent<ParticleSystem>();var main=fx.main;main.playOnAwake=false;main.loop=false;main.duration=.1f;main.startLifetime=.07f;main.startSpeed=1;main.startSize=.08f;main.startColor=new Color(1,.7f,.1f);var emission=fx.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0, (short)6)});fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var fire=root.gameObject.AddComponent<SoldierFire>();fire.muzzle=muzzle;fire.animator=animator;fire.flash=fx;var demo=root.gameObject.AddComponent<SoldierDemoInput>();demo.weapon=fire;demo.enabled=false;
 var prefab=PrefabUtility.SaveAsPrefabAsset(root.gameObject,folder+"/Soldier.prefab");AssetDatabase.SaveAssets();Selection.activeObject=prefab;EditorGUIUtility.PingObject(prefab);EditorUtility.DisplayDialog("Soldier generated", "Prefab: "+folder+"\nHumanoid valid: "+(avatar.isValid&&avatar.isHuman)+"\nAssign Animator Controller and holding/aim animation. See README.","OK");}finally{DestroyImmediate(root.gameObject);}}
 Material Mat(string n,Color c,bool camo,float smooth){int r=resolution;var tex=new Texture2D(r,r,TextureFormat.RGBA32,true);var normal=new Texture2D(r,r,TextureFormat.RGBA32,true,true);var mask=new Texture2D(r,r,TextureFormat.RGBA32,true,true);var pixels=new Color32[r*r];var normals=new Color32[r*r];var masks=new Color32[r*r];for(int y=0;y<r;y++)for(int x=0;x<r;x++){float u=x/(float)r,v=y/(float)r;float f=Mathf.PerlinNoise(Mathf.Floor(u*128)/9,Mathf.Floor(v*128)/9);float grain=Mathf.PerlinNoise(u*250,v*250);Color col=c*(.85f+grain*.25f);if(camo)col=(f>.63f?new Color(.19f,.23f,.13f):f<.36f?new Color(.44f,.43f,.26f):c)*(.82f+grain*.25f);col.a=1;int i=y*r+x;pixels[i]=col;float dx=Mathf.PerlinNoise(u*250+.15f,v*250)-grain,dy=Mathf.PerlinNoise(u*250,v*250+.15f)-grain;var nn=new Vector3(-dx*.8f,-dy*.8f,1).normalized;normals[i]=new Color(nn.x*.5f+.5f,nn.y*.5f+.5f,nn.z*.5f+.5f,1);masks[i]=new Color(n=="Metal"?.65f:0,0,0,smooth);}tex.SetPixels32(pixels);tex.Apply();normal.SetPixels32(normals);normal.Apply();mask.SetPixels32(masks);mask.Apply();var a=SaveTexture(tex,n+"_Albedo",false,false);var b=SaveTexture(normal,n+"_Normal",true,true);var m=SaveTexture(mask,n+"_MetallicSmoothness",true,false);var shader=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");var mat=new Material(shader);mat.SetTexture(mat.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",a);mat.SetTexture("_BumpMap",b);mat.EnableKeyword("_NORMALMAP");mat.SetTexture("_MetallicGlossMap",m);mat.EnableKeyword("_METALLICGLOSSMAP");if(mat.HasProperty("_Smoothness"))mat.SetFloat("_Smoothness",1);if(mat.HasProperty("_GlossMapScale"))mat.SetFloat("_GlossMapScale",1);AssetDatabase.CreateAsset(mat,folder+"/"+n+".mat");return mat;}
 Texture2D SaveTexture(Texture2D t,string n,bool linear,bool normal){string p=folder+"/"+n+".png";System.IO.File.WriteAllBytes(p,t.EncodeToPNG());DestroyImmediate(t);AssetDatabase.ImportAsset(p);var imp=(TextureImporter)AssetImporter.GetAtPath(p);imp.sRGBTexture=!linear;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.maxTextureSize=resolution;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
 void Shape(string n,string bone,Vector3 center,Vector3 radius,Material mat){var v=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();int rings=sides/2;for(int j=0;j<=rings;j++){float t=j/(float)rings;float phi=t*Mathf.PI;for(int i=0;i<=sides;i++){float u=i/(float)sides,a=u*2*Mathf.PI;float fold=1+.035f*Mathf.Sin(phi*18+a*3)*Mathf.Sin(phi);v.Add(center+Vector3.Scale(new Vector3(Mathf.Sin(phi)*Mathf.Cos(a),Mathf.Cos(phi),Mathf.Sin(phi)*Mathf.Sin(a))*fold,radius));uv.Add(new Vector2(u,1-t));}}for(int j=0;j<rings;j++)for(int i=0;i<sides;i++){int a=j*(sides+1)+i,b=a+sides+1;tr.AddRange(new[]{a,b,a+1,a+1,b,b+1});}var mesh=new Mesh{name=n};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tr,0);mesh.RecalculateNormals();mesh.RecalculateTangents();Skin(n,bone,mesh,mat);}
 void Box(string n,string bone,Vector3 p,Vector3 scale){Box(n,bone,p,scale,armor);}void Box(string n,string bone,Vector3 p,Vector3 scale,Material mat){var tmp=GameObject.CreatePrimitive(PrimitiveType.Cube);var mesh=Instantiate(tmp.GetComponent<MeshFilter>().sharedMesh);DestroyImmediate(tmp);var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i]=Vector3.Scale(v[i],scale)+p;mesh.vertices=v;mesh.RecalculateBounds();Skin(n,bone,mesh,mat);}
 void Skin(string n,string bone,Mesh mesh,Material mat){var go=new GameObject(n);go.transform.SetParent(root,false);var b=bones[bone];var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i]=root.InverseTransformPoint(b.TransformPoint(v[i]));mesh.vertices=v;var weights=new BoneWeight[v.Length];for(int i=0;i<v.Length;i++)weights[i]=new BoneWeight{boneIndex0=0,weight0=1};mesh.boneWeights=weights;mesh.bindposes=new[]{b.worldToLocalMatrix*root.localToWorldMatrix};mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/"+n+".asset");var sm=go.AddComponent<SkinnedMeshRenderer>();sm.sharedMesh=mesh;sm.sharedMaterial=mat;sm.bones=new[]{b};sm.rootBone=b;sm.updateWhenOffscreen=true;}
 void Prop(Transform parent,string n,Vector3 pos,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;DestroyImmediate(g.GetComponent<Collider>());}
}
}
